//! Shared initial bytes only; no expected output or source authority.
pub const CASES:&[&str]=&["hidden_order","singleton_quirks","allow_before_dedup","declaration_forms"];
pub fn files(case:&str)->Option<Vec<(String,Vec<u8>)>>{let mut out=vec![("deepquarry.dme".into(),b"// lexical policy: original compile manifest is deliberately independent\n".to_vec()),("tools/ci/lint_scopes.toml".into(),b"[lint.instance_list]\n".to_vec())];let mut add=|rel:&str,text:&str|out.push((rel.into(),text.as_bytes().to_vec()));match case{
"hidden_order"=>{add("code/z.dm","/obj/duplicate\n\tvar/list/shared = list()\n/obj/root\n\tvar/list/a = list()\n");add("code/.hidden.dm","/obj/hidden_file\n\tvar/list/a = list()\n");add("code/.hidden/a.dm","/obj/hidden_dir\n\tvar/list/a = list()\n");add("code/a/child.dm","/obj/duplicate\n\tvar/list/shared = list()\n");},
"singleton_quirks"=>{add("code/.hidden/globals.dm","SYSTEM_DEF(single)\nGLOBAL_DATUM_INIT(real, /datum/real, new)\nGLOBAL_DATUM_INIT(corrupt, /datum/corrupt, new\u{8})\n");add("code/vars.dm","/datum/system/single\n\tvar/list/x = list()\n/datum/controller/child\n\tvar/list/x = list()\n/datum/controllers\n\tvar/list/x = list()\n/datum/corrupt\n\tvar/list/x = list()\n/datum/corrupt/child\n\tvar/list/x = list()\n/datum/real\n\tvar/list/x = list()\n");},
"allow_before_dedup"=>{add("code/A.dm","/obj/duplicate\n\tvar/list/x = list() // ALLOW(instance_list/LOCAL): this table intentionally changes for each live instance\n/obj/duplicate2\n\tvar/list/x = list()\n");add("code/b.dm","/obj/duplicate\n\tvar/list/x = list()\n/obj/duplicate2\n\tvar/list/x = list() // ALLOW(instance_list/LATER): this table intentionally changes for each live instance\n");},
"declaration_forms"=>{add("code/forms.dm","/obj/forms\n\tvar/list/x = list()\n\tvar/static/list/shared = list()\n\tvar\n\t\tlist/nested = new\n\t\tconst/list/shared2 = list()\n\tproc/skip()\n\t\tvar/list/local = list()\n\tvar/list/after = new\n\tvar/list/tenth = new\n/obj/flat/var/list/raw = new\n/obj/flat/var/list/call = list()\n/obj/flat/var/staticky/list/quirk = new\n");},_=>return None}Some(out)}
